css:
@font-face { font-family: 'ShunxiY2KXiaolai'; src: url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/font/XiaolaiMono-Regular.woff2') format('woff2'); font-style: normal; font-weight: 400; font-display: swap; }
.prose-chapter { position: relative; isolation: isolate; box-sizing: border-box; overflow: hidden; width: 100%; max-width: 720px; min-width: 0; margin: 0 auto; padding: calc(33.333333% + 20px) 9% calc(33.333333% + 22px); border: 0; border-radius: 0; background: #FFFFFF url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/shunxi/y2kbackground.png') repeat; background-size: 512px 768px; color: var(--reader-ink); font-family: var(--reader-font); font-size: var(--reader-size); font-weight: 400; font-style: normal; line-height: var(--reader-leading); box-shadow: none; }
.prose-chapter::before, .prose-chapter::after { content: ''; position: absolute; left: 0; width: 100%; aspect-ratio: 3 / 1; background-size: 100% auto; background-repeat: no-repeat; background-position: center; pointer-events: none; z-index: -1; filter: saturate(.58); }
.prose-chapter::before { top: 0; background-image: url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/shunxi/y2ktop.png'); }
.prose-chapter::after { bottom: 0; background-image: url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/shunxi/y2kbottom.png'); }
.prose-title { position: relative; margin: 0 0 28px; padding: 0; font-family: inherit; font-size: 28px; line-height: 1.6; font-weight: 400; letter-spacing: .07em; text-align: center; text-indent: 0; color: #42638D; overflow-wrap: anywhere; text-shadow: none; }
.paragraph { margin: 0 0 1.25em; padding: 0; font-family: inherit; font-size: inherit; font-weight: 400; font-style: normal; line-height: inherit; letter-spacing: .02em; text-indent: 0; text-align: left; overflow-wrap: anywhere; text-shadow: none; }
.paragraph:last-of-type { margin-bottom: 0; }
.paragraph q, .paragraph .prose-quote { color: #B85F80; background: #FFF0F5; padding: .08em .15em; border-radius: 3px; box-decoration-break: clone; -webkit-box-decoration-break: clone; quotes: none; font-weight: inherit; font-style: inherit; text-decoration: none; }
.paragraph strong { font-weight: 700; color: #355B89; }
.paragraph em { font-style: italic; color: #637491; }
.paragraph del { color: #79869A; text-decoration: line-through; text-decoration-thickness: 1px; }
.paragraph code { font-family: inherit; color: #4C6485; background: #E8F0FC; font-size: .9em; padding: .1em .3em; border-radius: 3px; }
@media (max-width: 400px) { .prose-chapter { padding-left: 8%; padding-right: 8%; } .prose-title { font-size: 26px; } }
